    periop: '原則として手術当日朝まで継続する. Dravet 症候群は発熱, 環境温変化, 光刺激, 興奮といった誘因で容易にてんかん重積を起こす疾患であり, 周術期には 発熱を避ける, 過度な加温を避ける, 十分な鎮静・不安軽減を行う ことが重要である. 注射剤がないため, 内服不能期間は静注可能な抗てんかん薬 (レベチラセタム点滴静注, ミダゾラム持続静注など) で補う. 麻酔科的に最も重要なのは 強力な CYP 阻害作用 で, CYP3A4 基質のミダゾラム, フェンタニル, CYP2C19 基質のジアゼパム, CYP1A2 基質のカフェイン・ロピバカイン, CYP2D6 基質のコデイン・トラマドール・オンダンセトロンなど広範な麻酔関連薬の代謝を阻害し作用を延長・増強させるため, これらは減量して用いる. 併用中のクロバザムの活性代謝物ノルクロバザム濃度が数倍に上昇しており, ベースラインで強い鎮静状態にあることを前提に麻酔計画を立てる. Dravet 症候群では SCN1A 変異があるため, 理論的に Na チャネル遮断薬 (リドカイン, フェニトイン, カルバマゼピン) は発作を悪化させうるとされ, 局所麻酔薬の使用量には配慮する',
