    periop: '原則として手術当日朝まで継続する. 突然中止すると抑うつの再燃と中断症候群 (不安, 不眠, 悪心, 感覚異常) を招くため, 短期絶食程度で休薬しない. ただし麻酔科的には以下に注意する. (1) 抗コリン作用が強く, 術後せん妄・尿閉・イレウス・口渇のリスクが上がる. アトロピン, スコポラミン, 抗ヒスタミン薬の重ね掛けは避ける. (2) キニジン様のNaチャネル遮断作用でQRS幅延長・QT延長・催不整脈をきたすので術前12誘導心電図を確認する. QTc延長例ではセボフルラン, ドロペリドール, オンダンセトロンなど追加のQT延長薬を控え, K・Mgを補正する. (3) ノルアドレナリン再取り込み阻害のため昇圧薬への反応が変化する. 直接型 (フェニレフリン, アドレナリン, ノルアドレナリン) は作用が増強し過剰昇圧をきたしうるため通常量の1/3-1/2から慎重に開始し, 間接型 (エフェドリン) は貯蔵ノルアドレナリンが遊離されにくく反応が減弱しうる. 添付文書にもアドレナリン作動薬の作用増強が記載されている. (4) 抗コリン作用のためネオスチグミンによるリバースが効きにくい印象があり, スガマデクスが使いやすい. (5) トラマドール, ペチジン, フェンタニル, メチレンブルー, リネゾリドとの併用でセロトニン症候群のリスク. (6) MAO阻害薬 (セレギリン等) との併用は禁忌',
