    emergencyDose: '注射剤がないため, 経口不能時の代替はドパストン静注 (レボドパ換算で調節) またはロチゴチン貼付剤. 完全な中断は無動性クリーゼ・悪性症候群様症状を招くため回避する',
    periop: '手術当日の朝も通常通り内服し, 可能な限り早期に内服を再開する. レボドパの血漿中半減期は約1-3時間と極めて短いため, 数回の内服スキップだけでもパーキンソン症状の急激な悪化, 無動性クリーゼ, 悪性症候群様の症状 (高熱, 意識障害, 高度の筋強剛, 不随意運動, ショック状態) を来しうる. 経口摂取が数日以上不能と見込まれる場合は, 術前に神経内科・薬剤部と相談し, レボドパ静注製剤 (ドパストン) や経鼻経管投与, ロチゴチン貼付剤への一時切替を計画する (換算の一例として, 元のレボドパ1日量300mg未満ならドパストン1回50mg1日1回, 300-600mgなら1日2回, 600mg超なら1日3回, いずれも生理食塩液または5%ブドウ糖液100mLに希釈し約2時間かけて点滴静注する施設プロトコル報告がある. 貼付剤 (ニュープロパッチ等) を使用中の場合はそのまま継続する). 麻酔管理では, (1) 制吐薬に中枢性ドパミン拮抗薬 (メトクロプラミド, ドロペリドール, ハロペリドール, プロクロルペラジン等) を用いるとパーキンソン症状が急激に悪化するため避け, ドンペリドンやオンダンセトロン等5-HT3拮抗薬を選択する, (2) セレギリン・ラサギリン等MAO-B阻害薬を併用中の患者ではペチジン, トラマドール, タペンタドールが禁忌であることに留意する, (3) 術後は誤嚥・不動化による合併症を避けるためできる限り早期にレボドパ内服を再開する, の3点に注意する',
    mechanism: '末梢のドパ脱炭酸酵素阻害薬カルビドパを配合し, レボドパが脳血液関門を通過する前に末梢でドパミンへ変換されるのを抑制する. これにより少ないレボドパ量で脳内ドパミン濃度を高め, 悪心などの末梢性副作用も軽減する. レボドパ単独投与では脳内に到達するレボドパはごくわずかである',
    packageInsertReviewed: true,
