    periop: '手術当日朝まで通常通り内服し, 可能な限り早期に再開する. 急な中断でパーキンソン症状の急激な悪化, 悪性症候群様症状 (高熱, 意識障害, 高度の筋強剛, 不随意運動) を来しうる. 経口摂取不能が見込まれる場合はレボドパ量を基準に静注製剤 (ドパストン) や貼付剤への一時切替を神経内科・薬剤部と相談する. 添付文書の相互作用表に全身麻酔薬ハロタン等との併用で不整脈のおそれが明記されている (末梢でレボドパ由来のドパミンがβ1受容体を刺激し強心作用を示す一方, ハロゲン化吸入麻酔薬は心筋の被刺激性亢進作用を示すため). 現在の主流であるセボフルラン・デスフルランはハロタンに比べ心筋感受性の亢進作用は弱いとされるが, 術中の不整脈には留意する. 制吐薬は中枢性ドパミン拮抗薬 (メトクロプラミド, ドロペリドール, ハロペリドール, プロクロルペラジン等) を避け, ドンペリドンやオンダンセトロンを用いる. MAO-B阻害薬併用例ではペチジン・トラマドール・タペンタドールが禁忌である点はメネシットと共通の注意点である',
    mechanism: '末梢のドパ脱炭酸酵素阻害薬ベンセラジドを配合し, レボドパが脳血液関門を通過する前に末梢でドパミンへ変換されるのを抑制する. 少ないレボドパ量で脳内ドパミン濃度を高め, 悪心などの末梢性副作用を軽減する. 機序上メネシットと本質的な差はないが, ドパ脱炭酸酵素阻害薬との配合比が異なる (本剤4:1, メネシット10:1)',
