    mechanism: 'レボドパはドパミンの前駆物質であり, 静注後血液脳関門を通過して脳内に取り込まれ, 脳内でドパミンに転換されてパーキンソン病・パーキンソン症候群の症状を改善する. 内服のレボドパ・カルビドパ (メネシット) 等と異なり末梢ドパ脱炭酸酵素阻害薬を含まないため, 末梢でのドパミン転換が起こりやすい',
