  Drug(
    name: 'セレギリン塩酸塩',
    brand: 'エフピー',
    category: DrugCategory.psychotropic,
    spec: 'エフピーOD錠2.5 (口腔内崩壊錠, 1錠中セレギリン塩酸塩2.5mg)',
    dose: '・レボドパ含有製剤併用時/非併用時とも共通: 1日1回2.5mgを朝食後投与から開始し, 2週毎に1日量として2.5mgずつ増量, 最適投与量を定めて維持量とする (レボドパ併用時の標準維持量は1日7.5mg)\n'
        '・1日量5.0mg以上は朝食後・昼食後に分服する. 7.5mgの場合は朝食後5.0mg, 昼食後2.5mg\n'
        '・1日10mgを超えない (増量による更なる効果は認められず, 非選択的MAO阻害の危険性が増す)',
    forms: DrugFormAvailability(
      hasInjection: false,
      hasOral: true,
      summary: '内服のみ (口腔内崩壊錠). 国内に注射剤はない',
    ),
    periop: '手術当日朝までの継続が基本だが, 最重要なのは併用オピオイド・向精神薬の選択である. ペチジン塩酸塩含有製剤, トラマドール塩酸塩, タペンタドール塩酸塩を投与中の患者への投与は禁忌であり, 逆にこれらの薬剤を本剤投与中の患者に開始してはならない (高度の興奮, 精神錯乱, セロトニン症候群のリスク). 周術期に鎮痛が必要な場合はフェンタニル, レミフェンタニル, モルヒネ, オキシコドン等 (ペチジン・トラマドール・タペンタドール以外) を選択する. 三環系抗うつ薬・四環系抗うつ薬・SSRI・SNRI等セロトニン作動性薬剤も禁忌または要間隔設定であり, 術前後の向精神薬併用歴を確認する. 選択的MAO-B阻害薬としてMAO-Aに対する阻害は弱く, 非選択的MAOIで問題となる高血圧クリーゼやチーズ効果は通常量では起こしにくいが, 過量投与やCYP2D6/3A4阻害薬併用でMAO-B選択性が低下すると, 交感神経刺激薬 (エフェドリン等間接作用性昇圧薬) との併用で血圧上昇・頻脈が増強されるおそれがあるため, 昇圧薬が必要な場合は直接作用性のフェニレフリン・ノルアドレナリンを少量から用いることが望ましい. レボドパ製剤との併用でジスキネジア等が増強しうるため, 麻酔薬の中枢神経系抑制作用との相互作用にも注意する',
    mechanism: '脳内のB型モノアミン酸化酵素 (MAO-B) を不可逆的かつ選択的に阻害し, シナプス間隙でのドパミン分解を抑制する. 加えてドパミンのシナプスへの再取り込み阻害作用も有し, 細胞外ドパミン量を増加させてパーキンソン病症状を改善する',
    packageInsertReviewed: true,
    packageInsertRevision: '2024年2月改訂 (第1版)',
    packageInsertUrl: 'https://www.kegg.jp/medicus-bin/japic_med?japic_code=00053454',
    notes: [
      DrugNote(
