    periop: '手術当日朝までの継続が基本. 本剤はレボドパを含まないドパミンアゴニストであり, 急激な減量・中止で悪性症候群や薬剤離脱症候群 (無感情, 不安, うつ, 疲労感, 発汗, 疼痛) を誘発することがあるため, 経口不能が見込まれる場合は貼付剤 (ロチゴチン) への切替が実務上の選択肢となる (施設プロトコル例の換算表参照). 起立性低血圧が投与初期に出やすく, 脊髄くも膜下麻酔・脱水・出血時の血圧低下と重なりやすい点に注意する. 幻覚・妄想・せん妄が高齢者で多く, 術後せん妄との鑑別が必要になる. 制吐薬は本剤の効果を減弱させる中枢性ドパミン拮抗薬 (フェノチアジン系, ブチロフェノン系, メトクロプラミド, ドンペリドンも含めた記載あり) を避け, オンダンセトロン等5-HT3拮抗薬を優先する. アマンタジンやシメチジン等カチオン輸送系で腎排泄される薬剤との併用で腎クリアランス低下・副作用増強のおそれがある',
    mechanism: 'ドパミンD2受容体ファミリー (D2, D3, D4) に対し強い親和性を示す非麦角系ドパミン受容体作動薬. D1, D5受容体には親和性を示さない. 麦角系アゴニストと異なり心臓弁膜症等の線維性合併症のリスクが低いとされる',
    packageInsertReviewed: true,
