    mechanism: 'ドパミンD1様およびD2様受容体作動薬であり, 線条体において当該受容体を直接刺激することでパーキンソン病の運動機能障害に対する改善効果を示す. レボドパを介さず直接ドパミン受容体を刺激するため, 効果発現が非常に速い',
