    ),
    emergencyDose: 'てんかん重積状態の第2段階治療: 成人はレベチラセタムとして1回1000~3000mgを, 生理食塩液・乳酸リンゲル液・5%ブドウ糖注射液100mLで希釈し, 投与速度2~5mg/kg/分で静脈内投与する (添付文書上の正式な用法・用量). 1日最高投与量は3000mg. この速度は体重60~70kg程度の患者に1500~2000mgを投与する場合おおむね10~15分前後で終了する設定であり, 実臨床では「1000~3000mgを15分程度で点滴」と簡便に説明されることが多い (低体重例や上限量投与では速度規定上15分より延びうる). 腎機能低下例は下記の腎機能別用量を参考に減量する. 添付文書には診療ガイドライン (日本神経学会 てんかん診療ガイドライン) を参考に投与適否を判断することと明記されている',
    renalAdjust: 'クレアチニンクリアランス (CCr) に応じて成人1日投与量を調節する: CCr≧80mL/分は1000~3000mg, 50~79mL/分は1000~2000mg, 30~49mL/分は500~1500mg, <30mL/分 (非透析) は500~1000mg. 血液透析患者は1日500~1000mg (通常1回500mgを1日1回, 最高1回1000mg) を基本とし, 血液透析終了後に250~500mgを追加投与する (シミュレーションに基づく用量のため患者ごとに観察しながら調節する)',
    periop: '手術当日朝まで内服 (前日最終投与) を継続し, 術後内服再開までに数日以上を要する見込みならイーケプラ点滴静注500mgへ同一用量で切替可能 (経口・静注間のバイオアベイラビリティはほぼ同等). 麻酔科的には (1) 肝代謝をほとんど受けず (主に加水分解代謝と腎排泄), 他の抗てんかん薬・麻酔薬との相互作用が少なく周術期に併用しやすい, (2) 腎排泄型のため腎機能低下例・高齢者では用量調整と血中濃度モニタが必要で蓄積に注意する, (3) 傾眠・めまいがあり術後鎮静遷延や覚醒遅延に注意する, (4) 易刺激性・興奮・抑うつ・自殺念慮などの精神症状の既往がある患者では周術期の増悪徴候に留意する, の4点に注意する',
