        type: DrugNoteType.packageInsert,
      ),
      DrugNote(
        'てんかん重積状態における位置づけ',
        '2022年12月の適応拡大により, イーケプラ点滴静注500mgは国内で正式に「てんかん重積状態」の効能・効果と専用の用法・用量 (1回1000~3000mg, 2~5mg/kg/分) を取得した. 日本神経学会 てんかん診療ガイドラインの重積状態治療フローでは, ジアゼパム・ミダゾラムによる第1段階治療で発作が頓挫しない場合の第2段階治療薬の一つとして, ホスフェニトイン, フェノバルビタール, ラコサミドと並び位置づけられる. 心電図モニタリングの必須要件がホスフェニトインより緩やかで, 相互作用が少ない点が実地で選ばれやすい理由である',
