    emergencyDose: 'てんかん重積状態でベンゾジアゼピン系薬剤が無効な場合の第2段階治療の選択肢の一つ: ノーベルバール静注用250mgを日局注射用水または生理食塩液5mLに溶解し (約50mg/mL), フェノバルビタールとして15-20mg/kgを100mg/分を超えない速度 (10分以上かけて) で緩徐に静注する. 本剤は作用発現が遅く長時間作用型のため, 添付文書上も『てんかん重積状態の患者では速効性の薬剤を第一選択とし, 本剤は第二選択以降に使用することが望ましい』とされている. 投与により意識障害, 血圧低下, 呼吸抑制が高頻度に出現するため, 投与前に気道確保 (気管挿管の準備) を行い, 酸素, 吸引, 昇圧薬を手元に準備し, 投与中・投与後はパルスオキシメーター, 血圧, 呼吸数を連続監視する. フェノバール注射液 (有機溶媒を含み筋注・皮下注専用) は静脈内投与できず吸収も緩徐なため, てんかん重積状態の緊急静注には用いない',
