    periop: '抗てんかん薬として内服継続中の患者では手術当日も中止せず, 内服不能な周術期にはノーベルバール静注への切替を検討する. 薬物代謝酵素 (CYP3A4等) の誘導作用が強く, 非脱分極性筋弛緩薬, ワルファリン, ボリコナゾール, タダラフィル, リルピビリン等多数の薬剤 (併用禁忌を含む) の血中濃度・効果を低下させることがあるため周術期の薬物相互作用に注意する. 呼吸抑制・血圧低下は用量依存性に生じ, 他の中枢神経抑制薬 (ベンゾジアゼピン, オピオイド, 揮発性麻酔薬) との併用で相加的に増強する',
