    mechanism: '脳内GABAトランスアミナーゼ阻害等によりGABA濃度を上昇させ抑制系を増強するとともに, 電位依存性Naチャネル及びT型Caチャネルを抑制して神経細胞の過剰興奮を抑える. 複数の作用機序を併せ持つ広域スペクトラムの抗てんかん薬である',
